package com.careerguidance.dto.request;
import jakarta.validation.constraints.*; import java.util.*;
public class MentorRegistrationRequest {
 @NotBlank private String fullName; @Email @NotBlank private String email; @NotBlank @Size(min=8) private String password; private String phone; @NotBlank private String company; @NotBlank private String jobTitle; @NotNull @Min(1) private Integer experienceYears; private String expertise; private String bio; private String linkedinUrl; private String githubUrl; private String portfolioUrl; @NotEmpty private List<DocumentRequest> documents;
 public static class DocumentRequest { @NotBlank public String documentType; @NotBlank public String fileUrl; }
 public String getFullName(){return fullName;} public void setFullName(String v){fullName=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPassword(){return password;} public void setPassword(String v){password=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getCompany(){return company;} public void setCompany(String v){company=v;} public String getJobTitle(){return jobTitle;} public void setJobTitle(String v){jobTitle=v;} public Integer getExperienceYears(){return experienceYears;} public void setExperienceYears(Integer v){experienceYears=v;} public String getExpertise(){return expertise;} public void setExpertise(String v){expertise=v;} public String getBio(){return bio;} public void setBio(String v){bio=v;} public String getLinkedinUrl(){return linkedinUrl;} public void setLinkedinUrl(String v){linkedinUrl=v;} public String getGithubUrl(){return githubUrl;} public void setGithubUrl(String v){githubUrl=v;} public String getPortfolioUrl(){return portfolioUrl;} public void setPortfolioUrl(String v){portfolioUrl=v;} public List<DocumentRequest> getDocuments(){return documents;} public void setDocuments(List<DocumentRequest> v){documents=v;}
}
